function restore(serialized){const state=JSON.parse(serialized);data=state.data;figure=createFigure(state.figure);figureLibrary=Array.isArray(state.figureLibrary)?state.figureLibrary:figureLibrary;tableMode=state.tableMode||'column';currentAnalysis=state.currentAnalysis||'welch';roleKeys=state.roleKeys||{group:'group',value:'value'};multipleComparison=state.multipleComparison||'Holm';localStorage.setItem('statista-role-keys',JSON.stringify(roleKeys));localStorage.setItem('statista-multiple-comparison',multipleComparison);localStorage.setItem('statista-figure-library',JSON.stringify(figureLibrary));$('table-mode').value=tableMode;$('analysis-method').value=currentAnalysis;if($('multiple-comparison'))$('multiple-comparison').value=multipleComparison;updateHistoryButtons();refresh();syncFigureControls();renderFigureLibrary();}
