$('download-result').onclick = () => { if (!lastResult) { toast('Run an analysis before exporting a result'); return; } download(JSON.stringify({projectTitle:$('project-title').textContent,exportedAt:new Date().toISOString(),method:currentAnalysis,roles:roleKeys,result:lastResult,methods:currentMethods()},null,2), 'statista-result.json', 'application/json'); };
$('download-svg').insertAdjacentHTML('beforebegin', '<button class="text-button" id="download-png">PNG</button><button class="text-button" id="download-jpeg">JPEG</button>');
function rasterExport(type, extension){const svgText=new XMLSerializer().serializeToString($('chart'));const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=figure.width*2;canvas.height=figure.height*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,figure.width,figure.height);ctx.drawImage(image,0,0);canvas.toBlob(blob=>{const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`statista-figure.${extension}`;link.click();URL.revokeObjectURL(link.href);toast(`Downloaded statista-figure.${extension}`)},type,.95)};image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgText)}
$('download-svg').insertAdjacentHTML('beforebegin', '<button class="text-button" id="download-tiff">TIFF</button>');
$('download-png').onclick=()=>rasterExport('image/png','png');$('download-jpeg').onclick=()=>rasterExport('image/jpeg','jpg');$('download-tiff').onclick=()=>{const svgText=new XMLSerializer().serializeToString($('chart'));const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=figure.width*2;canvas.height=figure.height*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,figure.width,figure.height);ctx.drawImage(image,0,0);const blob=new Blob([encodeRgbTiff(canvas.width,canvas.height,ctx.getImageData(0,0,canvas.width,canvas.height).data)],{type:'image/tiff'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='statista-figure.tiff';link.click();URL.revokeObjectURL(link.href);toast('Downloaded statista-figure.tiff')};image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgText)};
try{validateFigure(figure)}catch{figure=createFigure()}
$('history-count').textContent = analysisHistory.length ? `${analysisHistory.length} saved` : '0 saved';
$('results-detail')?.remove(); document.querySelector('.analysis-panel').insertAdjacentHTML('beforeend', '<div id="results-detail" class="results-detail"></div>');
const supportedPlotTypes = new Set(['dot','bar','box','violin','swarm','histogram','density','scatter','line','connected-dot','mean-ci','mean-sem','mean-sd','point-range','errorbar','area','step','spline','ecdf','lollipop','survival','dose-response','qq','qq-quantile','bland-altman','heatmap','correlation','residual']);
$('chart-type').innerHTML = PLOT_TYPES.filter(([id]) => supportedPlotTypes.has(id)).map(([id,label]) => `<option value="${id}">${label}</option>`).join('');
$('chart-type').value = supportedPlotTypes.has(figure.type) ? figure.type : 'dot'; figure.type = $('chart-type').value;
$('chart').parentElement.insertAdjacentHTML('afterend', '<div class="figure-editor"><label>Figure title <input id="figure-title" type="text" value="Viability response" /></label><label>Control <input id="figure-color-a" type="color" value="#3f79c9" /></label><label>Treatment <input id="figure-color-b" type="color" value="#e77d69" /></label></div>');
$('figure-title').parentElement.insertAdjacentHTML('afterend', '<label>Panels <select id="panel-count"><option value="1">1</option><option value="2">2</option><option value="4">4</option></select></label>');
$('figure-title').parentElement.insertAdjacentHTML('afterend', '<div id="panel-controls" class="panel-controls"></div>');
$('figure-title').parentElement.insertAdjacentHTML('afterend', '<div class="figure-library-controls"><button class="quiet" id="save-figure">Save figure variant</button><div id="figure-library" class="figure-library"></div></div>');
$('figure-title').parentElement.insertAdjacentHTML('afterend', '<label>Style <select id="figure-template"><option value="journal">Journal</option><option value="presentation">Presentation</option><option value="minimal">Minimal</option></select></label>');
$('figure-title').parentElement.insertAdjacentHTML('afterend', '<label>X label <input id="figure-x-label" type="text" /></label><label>Y label <input id="figure-y-label" type="text" /></label><label><input id="figure-show-mean" type="checkbox" /> Show means</label>');
$('figure-title').value = figure.title; $('figure-color-a').value = figure.colors[0]; $('figure-color-b').value = figure.colors[1];
$('figure-x-label').value = figure.xLabel; $('figure-y-label').value = figure.yLabel;
$('figure-show-mean').checked = figure.showMean;
const figureColumns = [...new Set(data.flatMap(row => Object.keys(row)))].filter(key => data.some(row => Number.isFinite(Number(row[key])))); $('figure-title').parentElement.insertAdjacentHTML('afterend', `<label>X <select id="figure-x">${figureColumns.map(key => `<option value="${key}">${key}</option>`).join('')}</select></label><label>Y <select id="figure-y">${figureColumns.map(key => `<option value="${key}">${key}</option>`).join('')}</select></label>`); if (figure.xKey) $('figure-x').value = figure.xKey; if (figure.yKey) $('figure-y').value = figure.yKey;
$('figure-show-mean').parentElement.insertAdjacentHTML('afterend', '<label>Point size <input id="figure-point-size" type="number" min="1" max="20" step="1" /></label><label>Line width <input id="figure-stroke-width" type="number" min="0.5" max="8" step="0.5" /></label><label>Y min <input id="figure-y-min" type="number" step="any" placeholder="auto" /></label><label>Y max <input id="figure-y-max" type="number" step="any" placeholder="auto" /></label><label>Annotation <input id="figure-annotation" type="text" placeholder="e.g. p = 0.03" /></label><button class="text-button" id="add-annotation">＋ Add</button><div id="annotation-list"></div>');
$('figure-point-size').value = figure.pointSize; $('figure-stroke-width').value = figure.strokeWidth; $('figure-y-min').value = Number.isFinite(figure.yMin) ? figure.yMin : ''; $('figure-y-max').value = Number.isFinite(figure.yMax) ? figure.yMax : '';
function renderAnnotationList(){const target=$('annotation-list');if(!target)return;target.innerHTML=(figure.annotations||[]).map((annotation,index)=>`<button class="text-button" data-remove-annotation="${index}" title="Remove annotation">${annotation.label||'annotation'} ×</button>`).join(' ');target.querySelectorAll('[data-remove-annotation]').forEach(button=>button.onclick=()=>{checkpoint();figure.annotations.splice(Number(button.dataset.removeAnnotation),1);persistAndRenderDerived();renderAnnotationList();});}
renderAnnotationList();
$('save-figure').onclick=()=>{const title=prompt('Name this figure variant',figure.title||`Figure ${figureLibrary.length+1}`);if(!title)return;figureLibrary=[...figureLibrary,{...JSON.parse(JSON.stringify(figure)),title}];localStorage.setItem('statista-figure-library',JSON.stringify(figureLibrary));renderFigureLibrary();toast(`Saved ${title}`);};
renderFigureLibrary();
$('add-annotation').onclick=()=>{const label=$('figure-annotation').value.trim();if(!label)return;checkpoint();figure.annotations=[...(figure.annotations||[]),{label,x1:170,x2:430,y:45+figure.annotations.length*24}];$('figure-annotation').value='';persistAndRenderDerived();renderAnnotationList();};
[['figure-point-size','pointSize'],['figure-stroke-width','strokeWidth']].forEach(([id,key])=>$(id).addEventListener('change',event=>{checkpoint();figure[key]=Number(event.target.value);persistAndRenderDerived();}));
[['figure-y-min','yMin'],['figure-y-max','yMax']].forEach(([id,key])=>$(id).addEventListener('change',event=>{checkpoint();figure[key]=event.target.value===''?null:Number(event.target.value);persistAndRenderDerived();}));
['figure-x','figure-y'].forEach(id => $(id).addEventListener('change', event => { checkpoint(); figure[id === 'figure-x' ? 'xKey' : 'yKey'] = event.target.value; persistAndRenderDerived(); }));
$('figure-show-mean').onchange = event => { checkpoint(); figure.showMean = event.target.checked; persistAndRenderDerived(); };
const panelCount = figure.panels?.length || 1; $('panel-count').value = String(panelCount);
if (figure.template) $('figure-template').value = figure.template;
$('figure-template').onchange = event => { checkpoint(); figure = applyFigureTemplate(figure, event.target.value); $('figure-title').value = figure.title; $('figure-color-a').value = figure.colors[0]; $('figure-color-b').value = figure.colors[1]; persistAndRenderDerived(); toast(`${event.target.value} figure style applied`); };
if (!figure.panels || figure.panels.length !== panelCount) figure.panels = [{type:figure.type,title:figure.title}];
renderPanelControls();
$('panel-count').onchange = event => { checkpoint(); const count=Number(event.target.value), types=['dot','box','histogram','line']; figure.panels=Array.from({length:count},(_,i)=>({type:types[i%types.length],title:i===0?figure.title:`Panel ${i+1}`})); renderPanelControls(); persistAndRenderDerived(); toast(`Figure now has ${count} panel${count===1?'':'s'}`); };
['figure-title','figure-color-a','figure-color-b','figure-x-label','figure-y-label'].forEach(id => { $(id).addEventListener('focus', () => checkpoint()); $(id).addEventListener('input', event => { if(id === 'figure-title') figure.title = event.target.value; if(id === 'figure-color-a') figure.colors[0] = event.target.value; if(id === 'figure-color-b') figure.colors[1] = event.target.value; if(id === 'figure-x-label') figure.xLabel = event.target.value; if(id === 'figure-y-label') figure.yLabel = event.target.value; document.querySelector('.chart-panel h3').textContent = figure.title; persistAndRenderDerived(); }); });
refresh();
